message.content:
const val N = 105
const val INF = 1_000_000_000_000_000L

val a = IntArray(N)
val d = Array(N) { LongArray(N) }
val dt = Array(N) { LongArray(N) }
val t = Array(N) { LongArray(N) }
val r = Array(N) { LongArray(N) }

var n = 0
var T = 0L

fun one(a: Array<LongArray>) {
    for (i in 0 until n) {
        for (j in 0 until n) {
            a[i][j] = 0L
        }
    }
}

fun copy(a: Array<LongArray>, b: Array<LongArray>) {
    for (i in 0 until n) {
        for (j in 0 until n) {
            b[i][j] = a[i][j]
        }
    }
}

fun mul(a: Array<LongArray>, b: Array<LongArray>, c: Array<LongArray>) {
    for (i in 0 until n) {
        for (j in 0 until n) {
            c[i][j] = -INF
            for (k in 0 until n) {
                c[i][j] = maxOf(c[i][j], a[i][k] + b[k][j])
            }
        }
    }
}

fun binpow(a: Array<LongArray>, b: Long, c: Array<LongArray>) {
    copy(a, t)
    one(c)
    var exp = b
    while (exp != 0L) {
        if ((exp and 1L) != 0L) {
            mul(c, t, r)
            copy(r, c)
        }
        mul(t, t, r)
        copy(r, t)
        exp = exp shr 1
    }
}

fun main() {
    val input1 = readLine()!!.split(" ").map(String::toInt).toIntArray()
    n = input1[0]
    T = input1[1].toLong()

    val input2 = readLine()!!.split(" ").map(String::toInt).toIntArray()
    for (i in 0 until n) {
        a[i] = input2[i]
    }

    for (s in 0 until n) {
        for (i in 0 until n) {
            if (a[i] < a[s]) {
                d[s][i] = -INF
            } else {
                d[s][i] = 1
                for (j in 0 until i) {
                    if (a[j] <= a[i]) {
                        d[s][i] = maxOf(d[s][i], d[s][j] + 1)
                    }
                }
            }
        }
    }

    binpow(d, T, dt)

    var res = 0L
    for (i in 0 until n) {
        for (j in 0 until n) {
            res = maxOf(res, dt[i][j])
        }
    }
    println(res)
}

