    for (i in 0 until n) {
        for (j in 0 until n) {
            b[i][j] = a[i][j]
        }
    }
}

fun mul(a: Array<LongArray>, b: Array<LongArray>, c: Array<LongArray>) {
    for (i in 0 until n) {
        for (j in 0 until n) {
            c[i][j] = -INF
            for (k in 0 until n) {
                c[i][j] = maxOf(c[i][j], a[i][k] + b[k][j])
            }
        }
    }
}

fun binpow(a: Array<LongArray>, b: Long, c: Array<LongArray>) {
    copy(a, t)
    one(c)
    var power = b
    while (power != 0L) {
        if ((power and 1L) != 0L) {
            mul(c, t, r)
            copy(r, c)
        }
        mul(t, t, r)
